  "headline": "FDA's shortage list shows clindamycin in 5% dextrose has been posted since 2023-03-21 and remains current for Baxter, Pfizer, Sagent, and Sandoz as of 2026-10-21",
  "headline_cites": ["E42", "E37", "E38", "E39", "E40"],
  "sentences": [
    {
      "text": "FDA first posted the shortage on 2023-03-21 and the listing remains current as of 2026-10-21, a duration of 43 months.",
      "cites": ["E42", "D10"]
    },
    {
      "text": "The shortage is listed for Baxter Healthcare, Pfizer Inc., Sagent Pharmaceuticals, and Sandoz Inc., all with current status.",
      "cites": ["E37", "E38", "E39", "E40"]
    },
    {
      "text": "Sagent notes it is selling through remaining short-dated inventory through December 2026.",
      "cites": ["E39"]
    },
    {
      "text": "Sandoz's label names InfoRLife SA as the manufacturing plant, but the plant is not placed in our records.",
      "cites": ["E9"]
    },
    {
      "text": "The rule-based best option is to buy from Civica, Inc., which is not on FDA's shortage list today and uses InfoRLife SA.",
      "cites": ["D7"]
    },
    {
      "text": "Corvale East has 11 days on hand, Corvale General has 15 days, and Corvale Lakeside has 19 days at current usage rates.",
      "cites": ["D1", "D2", "D3"]
    }
  ]
}
